"""Strict scenario-v2 configuration and authorized circuit truth decoding."""
import math
import re
from .protocol import ProtocolError, expect, integer, real, rpc, state as plant_state

SOLUTES = ('urea', 'sodium', 'potassium', 'chloride', 'bicarbonate', 'calcium')
KINDS = ('tube', 'resistor', 'clamp', 'dialyzer')


def keys(value, names):
    if not isinstance(value, dict) or set(value) != set(names.split()):
        raise ValueError('configuration fields: ' + names)


def number(value, low, high):
    # Compare bounded JSON integers before math.isfinite converts them to double.
    if type(value) not in (int, float) or not low <= value <= high or not math.isfinite(value):
        raise ValueError('configuration numeric range')
    return value


def index(value, low, high):
    if type(value) is not int or not low <= value <= high:
        raise ValueError('configuration index')
    return value


def vector(values, low, high):
    if not isinstance(values, list) or len(values) != len(SOLUTES):
        raise ValueError('solute vector')
    for value in values:
        number(value, low, high)


def validate(config, validate_m1):
    required = ('schema_version model seed ticks dt_ms blood_mL_min uf_mL_min '
                'resistance_mmHg_min_mL pressure_limit_mmHg patient_volume_mL faults circuit transport')
    keys(config, required)
    if type(config['schema_version']) is not int or config['schema_version'] != 2 or config['model'] != 'm2-circuit-1':
        raise ValueError('configuration version/model')
    base = {k: v for k, v in config.items() if k not in ('circuit', 'transport')}
    base.update(schema_version=1, model='m1-hd-1', faults=[])
    validate_m1(base)  # Scalar types/bounds must be checked before using them as dimensions.
    circuit, transport = config['circuit'], config['transport']
    keys(circuit, 'compliance_mL_mmHg edges pump_node pump_head_mmHg sensor_node sensor_edge dialyzer_edge profile')
    values, edges = circuit['compliance_mL_mmHg'], circuit['edges']
    if not isinstance(values, list) or not 1 <= len(values) <= 16:
        raise ValueError('node count')
    for value in values:
        number(value, 0.001, 10)
    if not isinstance(edges, list) or not 1 <= len(edges) <= 32:
        raise ValueError('edge count')
    for field in ('pump_node', 'sensor_node'):
        index(circuit[field], 1, len(values))
    for field in ('sensor_edge', 'dialyzer_edge'):
        index(circuit[field], 0, len(edges) - 1)
    number(circuit['pump_head_mmHg'], 1, 600)
    dialyzers = []
    for i, edge in enumerate(edges):
        if not isinstance(edge, list) or len(edge) != 5:
            raise ValueError('edge tuple')
        a, b, resistance, kind, closed = edge
        index(a, 0, len(values)); index(b, 0, len(values))
        if a == b or kind not in KINDS or type(closed) is not bool:
            raise ValueError('edge type')
        number(resistance, 0.01, 100)
        if kind == 'dialyzer':
            if a == 0:
                raise ValueError('dialyzer upstream must be compliant node')
            dialyzers.append(i)
    if dialyzers != [circuit['dialyzer_edge']]:
        raise ValueError('exactly one selected dialyzer')
    profile = circuit['profile']
    keys(profile, 'id provenance resistance_mmHg_min_mL kuf_mL_min_mmHg koa_mL_min sieving')
    if (not isinstance(profile['id'], str) or not re.fullmatch(r'[a-z0-9-]{1,48}', profile['id'])
            or profile['provenance'] != 'synthetic'):
        raise ValueError('profile identity/provenance')
    number(profile['resistance_mmHg_min_mL'], 0.01, 100)
    number(profile['kuf_mL_min_mmHg'], 0, 1)
    vector(profile['koa_mL_min'], 0, 3000); vector(profile['sieving'], 0, 1)
    keys(transport, 'blood_mmol_L dialysate_mmol_L dialysate_mL_min')
    vector(transport['blood_mmol_L'], 0, 1000); vector(transport['dialysate_mmol_L'], 0, 1000)
    number(transport['dialysate_mL_min'], 0, 1000)
    if not isinstance(config['faults'], list):
        raise ValueError('fault timeline')
    sensor_faults, seen = [], set()
    for fault in config['faults']:
        keys(fault, 'tick target value')
        index(fault['tick'], 0, config['ticks'] - 1)
        target = fault['target']
        if not isinstance(target, str) or (fault['tick'], target) in seen:
            raise ValueError('fault target/duplicate')
        seen.add((fault['tick'], target))
        if target.startswith('edge:'):
            if not re.fullmatch(r'edge:(0|[1-9][0-9]?)', target):
                raise ValueError('edge fault index')
            index(int(target[5:]), 0, len(edges) - 1)
            keys(fault['value'], 'resistance closed')
            number(fault['value']['resistance'], 0.01, 100)
            if type(fault['value']['closed']) is not bool:
                raise ValueError('clamp flag')
        elif target in ('control_sensor', 'protection_sensor'):
            sensor_faults.append(fault)
        else:
            raise ValueError('unsupported circuit fault')
    base.update(faults=sensor_faults)
    validate_m1(base)
    return config


def configure(admin, config):
    c, tr = config['circuit'], config['transport']
    p = c['profile']
    fields = ['CONFIG2', len(c['compliance_mL_mmHg']), len(c['edges']), c['pump_node'], c['pump_head_mmHg'],
              c['sensor_node'], c['sensor_edge'], c['dialyzer_edge'], p['resistance_mmHg_min_mL'], p['kuf_mL_min_mmHg']]
    fields.extend(c['compliance_mL_mmHg'])
    for a, b, r, kind, closed in c['edges']:
        fields.extend((a, b, r, KINDS.index(kind), int(closed)))
    expect(rpc(admin, *fields), 'OK', 1)
    transport(admin, config, tr['blood_mmol_L'])


def transport(admin, config, blood):
    p, tr = config['circuit']['profile'], config['transport']
    expect(rpc(admin, 'TRANSPORT3' if config['schema_version'] >= 3 else 'TRANSPORT2',
               tr['dialysate_mL_min'], *p['koa_mL_min'], *p['sieving'], *blood, *tr['dialysate_mmol_L']), 'OK', 1)


def state(response):
    if len(response) < 13 or response[0] not in ('CIRCUIT2', 'CIRCUIT3'):
        raise ProtocolError('circuit schema')
    n, t, nodes, edges = (integer(x) for x in response[1:5])
    coupled = response[0] == 'CIRCUIT3'
    if not 1 <= nodes <= 16 or not 1 <= edges <= 32 or len(response) != 13 + nodes + edges + (18 if coupled else 12):
        raise ProtocolError('circuit vector dimensions')
    scalar_names = ('pump_mL_min', 'return_mL_min', 'uf_mL_min', 'stored_mL', 'storage_change_mL',
                    'draw_tick_mL', 'return_tick_mL', 'uf_tick_mL')
    result = dict(sequence=n, time_ms=t)
    result.update((name, real(value, -1e9, 1e9)) for name, value in zip(scalar_names, response[5:13]))
    offset = 13
    for field, size in (('pressure_mmHg', nodes), ('edge_mL_min', edges),
                        ('diffusion_mmol_min', 6), ('convection_mmol_min', 6)):
        result[field] = [real(x, -1e9, 1e9) for x in response[offset:offset + size]]
        offset += size
    if coupled:
        result['clearance_mL_min'] = [real(x, 0, 2000) for x in response[offset:]]
        for name in ('diffusion_mmol_min', 'convection_mmol_min'):
            result['boundary_' + name] = result.pop(name)
    return result


def committed(response, coupled=False):
    if not response or response[0] != ('COMMITTED3' if coupled else 'COMMITTED2'):
        raise ProtocolError('atomic circuit commit schema')
    if len(response) <= 12 or response[12] != ('CIRCUIT3' if coupled else 'CIRCUIT2'):
        raise ProtocolError('commit payload version mismatch')
    result = plant_state(response[1:12])
    result['circuit'] = state(response[12:])
    return result

compartments.py:
"""Conservative synthetic body/circuit compartments; no clinical calibration."""
import copy
import math
from .circuit import keys, number, vector, index
from .protocol import ProtocolError

FIELDS = ('id provenance volume_mL concentration_mmol_L exchange_mL_min partition '
          'refill_mL_min prime_mL initial_weight_kg pco2_mmHg external_in_mL_min '
          'external_out_mL_min external_mmol_L generation_mmol_min')
# At the largest supported compartment this slack represents <=1e-7 mmol,
# below the unchanged whole-system 1e-6 mmol residual criterion. Never clip mass.
CONCENTRATION_CEILING = 1000 + 1e-9


def validate(config):
    keys(config, FIELDS + (' hemodynamics' if 'hemodynamics' in config else '') + (' extracorporeal' if 'extracorporeal' in config else ''))
    if 'extracorporeal' in config:
        from .distributed import validate_config
        validate_config(config['extracorporeal'])
        if 'hemodynamics' not in config or abs(sum(config['extracorporeal']['volumes_mL'])-config['prime_mL'])>1e-7:raise ValueError('distributed initial inventory')
    if 'hemodynamics' in config:
        h=config['hemodynamics'];keys(h,'initial_hematocrit vascular_mL protein_g_dL temperature_C refill_mL_min')
        for k,lo,hi in [('initial_hematocrit',.1,.6),('vascular_mL',1000,10000),('protein_g_dL',1,15),('temperature_C',30,42),('refill_mL_min',0,2000)]:number(h[k],lo,hi)

    if config['provenance'] != 'synthetic' or config['id'] not in ('synthetic-baseline', 'synthetic-overload', 'synthetic-imbalance', 'synthetic-custom'):
        raise ValueError('patient identity/provenance')
    if not isinstance(config['volume_mL'], list) or len(config['volume_mL']) != 2:
        raise ValueError('two body volumes required')
    for value in config['volume_mL']: number(value, 100, 100000)
    if not 1000 <= sum(config['volume_mL']) <= 100000:
        raise ValueError('total body volume')
    if 'hemodynamics' in config and h['vascular_mL']*(1-h['initial_hematocrit'])>=config['volume_mL'][0]:raise ValueError('vascular plasma exceeds extracellular water')
    concentrations = config['concentration_mmol_L']
    if not isinstance(concentrations, list) or len(concentrations) != 2:
        raise ValueError('two concentration vectors required')
    for values in concentrations: vector(values, 0, 1000)
    vector(config['exchange_mL_min'], 0, 2000)
    vector(config['partition'], 0.001, 1000)
    vector(config['external_mmol_L'], 0, 1000)
    vector(config['generation_mmol_min'], 0, 10)
    for key, low, high in [('refill_mL_min', 0, 5000), ('prime_mL', 10, 1000),
                           ('initial_weight_kg', 1, 300), ('pco2_mmHg', 10, 100),
                           ('external_in_mL_min', 0, 100), ('external_out_mL_min', 0, 100)]:
        number(config[key], low, high)
    if config['initial_weight_kg'] < sum(config['volume_mL']) / 1000:
        raise ValueError('weight cannot be less than initial body water mass')
    return config


def validate_scenario(config, validate_circuit):
    keys(config, 'schema_version model seed ticks dt_ms blood_mL_min uf_mL_min resistance_mmHg_min_mL '
                'pressure_limit_mmHg patient_volume_mL faults circuit transport patient')
    if type(config['schema_version']) is not int or config['schema_version'] != 3 or config['model'] != 'm3-patient-1':
        raise ValueError('coupled scenario version/model')
    patient = validate(config['patient'])
    base = {k: v for k, v in config.items() if k != 'patient'}
    base.update(schema_version=2, model='m2-circuit-1')
    validate_circuit(base)
    if abs(sum(patient['volume_mL']) - config['patient_volume_mL']) > 1e-8:
        raise ValueError('initial patient volume mismatch')
    if patient['concentration_mmol_L'][0] != config['transport']['blood_mmol_L']:
        raise ValueError('initial blood concentration mismatch')
    return config


def validate_snapshot(state, online=False, lifecycle=False):
    if 'distributed' in state:
        d=state['distributed'];keys(d,'compartments dialysate_concentration_mmol_L dialysate_volume_mL dialysate_input_mmol dialysate_output_mmol dialysate_transfer_mmol dialysate_residual_mmol')
        number(d['dialysate_volume_mL'],1,2000)
        for k in ('dialysate_input_mmol','dialysate_output_mmol','dialysate_transfer_mmol'):vector(d[k],-1e9,1e9)
        vector(d['dialysate_residual_mmol'],-1e-6,1e-6)
        if len(d['compartments'])!=16 or len(d['dialysate_concentration_mmol_L'])!=12:raise ProtocolError('distributed snapshot size')
        for c in d['compartments']:
            keys(c,'name volume_mL concentration_mmol_L rbc_mL protein_g hematocrit protein_g_dL')
            number(c['volume_mL'],.001,1000);number(c['rbc_mL'],0,c['volume_mL']*.8);number(c['protein_g'],0,5000)
            number(c['hematocrit'],0,.8);number(c['protein_g_dL'],0,40);vector(c['concentration_mmol_L'],0,CONCENTRATION_CEILING)
        for row in d['dialysate_concentration_mmol_L']:vector(row,0,CONCENTRATION_CEILING)
        validate_snapshot({k:v for k,v in state.items() if k!='distributed'},online,lifecycle)
        return state
    if 'hemodynamics' in state:
        h=state['hemodynamics']
        keys(h,'hematocrit vascular_mL circuit_rbc_mL vascular_rbc_mL lost_rbc_mL rbc_residual_mL protein_g_dL temperature_C refill_mL circuit_hematocrit circuit_protein_g_dL protein_residual_g vascular_protein_g circuit_protein_g lost_protein_g')
        number(h['hematocrit'],0,.7);number(h['vascular_mL'],1,20000)
        for k in ('circuit_rbc_mL','vascular_rbc_mL','lost_rbc_mL'):number(h[k],0,20000)
        for k in ('vascular_protein_g','circuit_protein_g','lost_protein_g'):number(h[k],0,5000)
        number(h['circuit_hematocrit'],0,.8);number(h['circuit_protein_g_dL'],0,40);number(h['protein_residual_g'],-1e-6,1e-6)
        number(h['rbc_residual_mL'],-1e-6,1e-6);number(h['protein_g_dL'],0,30);number(h['temperature_C'],30,42);number(h['refill_mL'],-10000,10000)
        validate_snapshot({k:v for k,v in state.items() if k!='hemodynamics'},online,lifecycle)
        return state
    if lifecycle:
        names = ('flush_in_mL', 'flush_out_mL', 'flush_input_mmol', 'flush_output_mmol')
        for name in names[:2]: number(state.get(name), 0, 1e9)
        for name in names[2:]: vector(state.get(name), 0, 1e9)
        validate_snapshot({k: v for k, v in state.items() if k not in names}, online=True)
        return state
    if online:
        number(state.get('substitution_mL'), 0, 1e9)
        vector(state.get('substitution_mmol'), 0, 1e9)
        base = {k: v for k, v in state.items() if k not in ('substitution_mL', 'substitution_mmol')}
        validate_snapshot(base)
        return state
    keys(state, 'sequence time_ms volume_mL mass_mmol concentration_mmol_L gross_uf_mL external_in_mL '
                'external_out_mL net_patient_loss_mL weight_kg illustrative_pH mass_residual_mmol '
                'diffusive_mmol convective_mmol input_mmol output_mmol')
    index(state['sequence'], 0, 99999); index(state['time_ms'], 0, 100000000)
    if not isinstance(state['volume_mL'], list) or len(state['volume_mL']) != 3:
        raise ProtocolError('compartment volume vector')
    for v in state['volume_mL']: number(v, 1, 100000)
    for name, limit in [('mass_mmol', 100000), ('concentration_mmol_L', CONCENTRATION_CEILING)]:
        if not isinstance(state[name], list) or len(state[name]) != 3:
            raise ProtocolError('compartment matrix')
        for row in state[name]: vector(row, 0, limit)
    for name in ('diffusive_mmol', 'convective_mmol', 'input_mmol', 'output_mmol'):
        vector(state[name], -1e9, 1e9)
    vector(state['mass_residual_mmol'], -1e-6, 1e-6)
    for name in ('gross_uf_mL', 'external_in_mL', 'external_out_mL'): number(state[name], 0, 1e9)
    number(state['net_patient_loss_mL'], -100000, 100000)
    number(state['weight_kg'], 0, 400)
    if state['illustrative_pH'] is not None: number(state['illustrative_pH'], -400, 400)
    return state


class Sum:
    def __init__(self):
        self.value = self.correction = 0.0

    def add(self, value):
        increment = value - self.correction
        updated = self.value + increment
        self.correction = (updated - self.value) - increment
        self.value = updated


def solve(matrix, rhs):
    """Tiny pivoted balance solve. Inputs remain unchanged on rejection."""
    a = [list(row) + [value] for row, value in zip(matrix, rhs)]
    for col in range(3):
        pivot = max(range(col, 3), key=lambda row: abs(a[row][col]))
        a[col], a[pivot] = a[pivot], a[col]
        if not math.isfinite(a[col][col]) or abs(a[col][col]) < 1e-12:
            raise ProtocolError('singular compartment balance')
        for row in range(col + 1, 3):
            multiplier = a[row][col] / a[col][col]
            for j in range(col, 4): a[row][j] -= multiplier * a[col][j]
    result = [0.0] * 3
    for row in range(2, -1, -1):
        result[row] = (a[row][3] - math.fsum(a[row][j] * result[j] for j in range(row + 1, 3))) / a[row][row]
    if not all(math.isfinite(x) and 0 <= x <= CONCENTRATION_CEILING for x in result):
        raise ProtocolError('concentration outside model bounds')
    return result


class Compartments:
    def __init__(self, config, online=False, lifecycle=False):
        self.online = online
        self.lifecycle = lifecycle
        self.config = copy.deepcopy(validate(config))
        self.volume = [*map(float, config['volume_mL']), float(config['prime_mL'])]
        self.initial_body = sum(self.volume[:2])
        self.concentration = copy.deepcopy(config['concentration_mmol_L']) + [list(config['concentration_mmol_L'][0])]
        self.mass = [[v * c / 1000 for c in values] for v, values in zip(self.volume, self.concentration)]
        self.initial_mass = [math.fsum(row[i] for row in self.mass) for i in range(6)]
        self.water = {name: Sum() for name in (('uf', 'in', 'out', 'sub') if online else ('uf', 'in', 'out'))}
        self.solute = {name: [Sum() for _ in range(6)] for name in (('diffusive', 'convective', 'input', 'output', 'substitution') if online else ('diffusive', 'convective', 'input', 'output'))}
        if lifecycle:
            if not online: raise ProtocolError('lifecycle requires online fluid model')
            self.water.update({name: Sum() for name in ('flush_in', 'flush_out')})
            self.solute.update({name: [Sum() for _ in range(6)] for name in ('flush_input', 'flush_output')})
        self.next_sequence = self.time_ms = self.sequence = 0
        self.mass_residual = [0.0] * 6
        self.body_transfer = Sum()
        if 'hemodynamics' in config:
            h=config['hemodynamics'];self.vascular=h['vascular_mL'];self.initial_vascular=self.vascular
            self.cells=[self.vascular*h['initial_hematocrit'],0.0];self.initial_cells=sum(self.cells);self.lost_cells=0.0
            self.proteins=[(self.vascular-self.cells[0])*h['protein_g_dL']/100,0.0]
            self.initial_proteins=sum(self.proteins);self.lost_proteins=0.0
            self.refill_total=0.0
            self.initial_extravascular=self.initial_body-(self.vascular-self.cells[0])

        if 'extracorporeal' in config:
            from .distributed import initialize
            self.network=initialize(self)

    def snapshot(self):
        body = math.fsum(self.volume[:2])
        bicarbonate = self.concentration[0][4]
        hemo={}
        if 'hemodynamics' in self.config:
            hemo['hemodynamics']=dict(hematocrit=self.cells[0]/self.vascular,vascular_mL=self.vascular,
                circuit_hematocrit=self.cells[1]/self.volume[2],
                circuit_protein_g_dL=self.proteins[1]/(self.volume[2]-self.cells[1])*100,
                vascular_protein_g=self.proteins[0],circuit_protein_g=self.proteins[1],lost_protein_g=self.lost_proteins,
                protein_residual_g=sum(self.proteins)+self.lost_proteins-self.initial_proteins,
                circuit_rbc_mL=self.cells[1],vascular_rbc_mL=self.cells[0],lost_rbc_mL=self.lost_cells,
                rbc_residual_mL=sum(self.cells)+self.lost_cells-self.initial_cells,
                protein_g_dL=self.proteins[0]/(self.vascular-self.cells[0])*100,
                temperature_C=self.config['hemodynamics']['temperature_C'],refill_mL=self.refill_total)
        if hasattr(self,'network'):
            from .distributed import snapshot
            hemo['distributed']=snapshot(self.network)
        return dict(**hemo,**({name + '_mL': self.water[name].value for name in ('flush_in', 'flush_out')} if self.lifecycle else {}),
                    **(dict(substitution_mL=self.water['sub'].value) if self.online else {}),
                    sequence=self.sequence, time_ms=self.time_ms,
                    volume_mL=list(self.volume), mass_mmol=copy.deepcopy(self.mass),
                    concentration_mmol_L=copy.deepcopy(self.concentration),
                    gross_uf_mL=self.water['uf'].value, external_in_mL=self.water['in'].value,
                    external_out_mL=self.water['out'].value, net_patient_loss_mL=self.initial_body - body,
                    weight_kg=self.config['initial_weight_kg'] + (body - self.initial_body) / 1000,
                    illustrative_pH=(6.1 + math.log10(bicarbonate) - math.log10(0.03 * self.config['pco2_mmHg'])
                                     if bicarbonate > 0 else None),
                    mass_residual_mmol=list(self.mass_residual),
                    **{name + '_mmol': [s.value for s in values] for name, values in self.solute.items()})

    def advance(self, request):
        keys(request, 'sequence time_ms dt_ms draw_mL return_mL uf_mL stored_mL clearance_mL_min sieving dialysate_mmol_L'
             + (' pre_mL post_mL substitution_mmol_L' if self.online else '')
             + (' flush_in_mL flush_out_mL flush_mmol_L' if self.lifecycle else '')
             + (' distributed' if hasattr(self,'network') else '')
             + (' rinseback' if self.lifecycle and 'rinseback' in request else ''))
        for key in ('sequence', 'time_ms', 'dt_ms'):
            if type(request[key]) is not int: raise ProtocolError('clock type')
        if (request['sequence'] != self.next_sequence or request['time_ms'] != self.time_ms
                or not 1 <= request['dt_ms'] <= 1000 or self.next_sequence >= 100000):
            raise ProtocolError('patient tick order')
        dt = request['dt_ms'] / 60000
        for key, high in [('draw_mL', (1000 if hasattr(self,'network') else 500) * dt), ('return_mL', 100000), ('uf_mL', (140 if self.online else 20) * dt), ('stored_mL', 96000)]:
            number(request[key], -self.config['prime_mL']+1 if key=='stored_mL' and 'hemodynamics' in self.config else 0, high)
        vector(request['clearance_mL_min'], 0, 2000)
        vector(request['sieving'], 0, 1)
        vector(request['dialysate_mmol_L'], 0, CONCENTRATION_CEILING if self.online else 1000)
        draw, returned, uf = (request[k] for k in ('draw_mL', 'return_mL', 'uf_mL'))
        flush_in = flush_out = 0
        flush_c = [0] * 6
        if self.lifecycle:
            flush_in = number(request['flush_in_mL'], 0, (1000 if hasattr(self,'network') else 500) * dt)
            flush_out = number(request['flush_out_mL'], 0, 100000)
            flush_c = request['flush_mmol_L']; vector(flush_c, 0, CONCENTRATION_CEILING)
            rinseback=request.get('rinseback',False)
            if type(rinseback) is not bool:raise ProtocolError('rinseback flag')
            if rinseback and (draw or uf or flush_out or any(request['clearance_mL_min'])):
                raise ProtocolError('rinseback must have saline inlet and patient return only')
            if not rinseback and (flush_in or flush_out) and (draw or returned or uf or any(request['clearance_mL_min'])):
                raise ProtocolError('simultaneous patient connection and external flushing')
        pre = post = 0
        replacement_c = [0] * 6
        if self.online:
            pre, post = (number(request[k], 0, 120 * dt) for k in ('pre_mL', 'post_mL'))
            if pre > 0 and post > 0: raise ProtocolError('two simultaneous replacement routes')
            replacement_c = request['substitution_mmol_L']
            vector(replacement_c, 0, CONCENTRATION_CEILING)
            if (flush_in or flush_out) and (pre or post): raise ProtocolError('replacement during external flushing')
        circuit_volume = self.config['prime_mL'] + request['stored_mL']
        if abs(circuit_volume - self.volume[2] - draw - pre + returned + uf - flush_in + flush_out) > 1e-8:
            raise ProtocolError('circuit water mismatch')
        incoming, outgoing = (self.config[k] * dt for k in ('external_in_mL_min', 'external_out_mL_min'))
        water = copy.deepcopy(self.water)
        for name, value in [('uf', uf), ('in', incoming), ('out', outgoing)]: water[name].add(value)
        if self.online: water['sub'].add(pre + post)
        if self.lifecycle:
            water['flush_in'].add(flush_in); water['flush_out'].add(flush_out)
        # Reconstruct body total from absolute conserved ledgers, avoiding drainage
        # drift at the volume ceiling; compare independent hydraulic deltas above.
        body_transfer = copy.deepcopy(self.body_transfer)
        if self.lifecycle:
            # Integrate only transfers crossing the body boundary. During an
            # isolated flush this is exactly zero, independently of cancellation
            # between large accumulated source/waste totals and circuit storage.
            body_transfer.add(math.fsum([returned, post, -draw]))
            body = math.fsum([self.initial_body, water['in'].value, -water['out'].value, body_transfer.value])
            whole_water = math.fsum([self.initial_body, water['in'].value, -water['out'].value,
                                    -water['uf'].value, water['sub'].value, -request['stored_mL'],
                                    water['flush_in'].value, -water['flush_out'].value, -body])
            if abs(whole_water) > 1e-6: raise ProtocolError('whole-system water conservation residual')
        else:
            body = math.fsum([self.initial_body, water['in'].value, -water['out'].value,
                              -water['uf'].value, water['sub'].value if self.online else 0, -request['stored_mL']])
        ve, vi = body - self.volume[1], self.volume[1]
        te, ti = self.config['volume_mL']
        kd = self.config['refill_mL_min'] * dt
        refill = kd * (vi / ti - ve / te) / (1 + kd * (1 / ti + 1 / te))
        ve += refill
        vi = body - ve
        volumes = [ve, vi, circuit_volume]
        if not 1 <= body <= 100000 or not all(1 <= v <= 100000 for v in volumes):
            raise ProtocolError('compartment volume outside model bounds')
        solute = copy.deepcopy(self.solute)
        concentrations = [[0.0] * 6 for _ in range(3)]
        masses = [[0.0] * 6 for _ in range(3)]
        residuals = []
        network=None
        if hasattr(self,'network'):
            from .distributed import solute_balance
            concentrations,masses,flux,network=solute_balance(self,request,volumes,refill,dt,incoming,outgoing)
            for i in range(6):
                for name,value in flux[i].items():solute[name][i].add(value)
                residual=math.fsum([*(row[i] for row in masses),solute['diffusive'][i].value,
                    solute['convective'][i].value,solute['output'][i].value,-solute['input'][i].value,
                    -solute['substitution'][i].value,-self.initial_mass[i],
                    solute['flush_output'][i].value-solute['flush_input'][i].value])
                if abs(residual)>1e-6:raise ProtocolError('distributed whole-system solute residual')
                residuals.append(residual)
        else:
            for i in range(6):
                exchange = self.config['exchange_mL_min'][i] * dt
                reverse = exchange / self.config['partition'][i]
                ei, ie = max(-refill, 0), max(refill, 0)
                kd = request['clearance_mL_min'][i] * dt
                conv = uf * request['sieving'][i]
                external = incoming * self.config['external_mmol_L'][i] + self.config['generation_mmol_min'][i] * dt * 1000
                matrix = [[ve + draw + outgoing + exchange + ei, -reverse - ie, -returned],
                          [-exchange - ei, vi + reverse + ie, 0],
                          [-draw, 0, circuit_volume + returned + flush_out + kd + conv]]
                rhs = [self.mass[0][i] * 1000 + external + post * replacement_c[i], self.mass[1][i] * 1000,
                       self.mass[2][i] * 1000 + kd * request['dialysate_mmol_L'][i] + pre * replacement_c[i] + flush_in * flush_c[i]]
                result = solve(matrix, rhs)
                for j in range(3):
                    concentrations[j][i] = result[j]
                    masses[j][i] = result[j] * volumes[j] / 1000
                for name, value in [('input', external / 1000), ('output', outgoing * result[0] / 1000),
                                    ('diffusive', kd * (result[2] - request['dialysate_mmol_L'][i]) / 1000),
                                    ('convective', conv * result[2] / 1000)]:
                    solute[name][i].add(value)
                if self.online: solute['substitution'][i].add((pre + post) * replacement_c[i] / 1000)
                if self.lifecycle:
                    solute['flush_input'][i].add(flush_in * flush_c[i] / 1000)
                    solute['flush_output'][i].add(flush_out * result[2] / 1000)
                residual = math.fsum([*(row[i] for row in masses), solute['diffusive'][i].value,
                                      solute['convective'][i].value, solute['output'][i].value,
                                      -solute['input'][i].value, -solute['substitution'][i].value if self.online else 0, -self.initial_mass[i],
                                      solute['flush_output'][i].value - solute['flush_input'][i].value if self.lifecycle else 0])
                if abs(residual) > 1e-6: raise ProtocolError('patient mass conservation residual')
                residuals.append(residual)
        # Validate the complete prospective response before mutating accepted state.
        proposed = copy.copy(self)
        proposed.volume, proposed.concentration, proposed.mass = volumes, concentrations, masses
        proposed.water, proposed.solute, proposed.mass_residual = water, solute, residuals
        proposed.body_transfer = body_transfer
        if network is not None:proposed.network=network
        proposed.sequence = self.next_sequence
        proposed.next_sequence += 1
        proposed.time_ms += request['dt_ms']
        if 'hemodynamics' in self.config:
            # Vascular volume has its own tissue-refilling dynamics. The solute
            # extracellular pool above is not treated as a blood volume.
            change=body-sum(self.volume[:2]);h=self.config['hemodynamics']
            v=self.vascular+change
            tissue=body-(v-self.cells[0])
            k=h['refill_mL_min']*dt
            refill=k*(tissue/self.initial_extravascular-v/self.initial_vascular)/(1+k*(1/self.initial_extravascular+1/self.initial_vascular))
            v+=refill
            if v<=self.cells[0] or v>20000:raise ProtocolError('vascular volume domain')
            # Implicit two-volume advection conserves RBC/protein through saline
            # priming, patient circulation and rinseback; neither crosses the membrane.
            a=1+draw/v;b=-returned/circuit_volume;c=-draw/v;d=1+(returned+flush_out)/circuit_volume
            determinant=a*d-b*c
            def retained(amount):return [(amount[0]*d-b*amount[1])/determinant,(a*amount[1]-c*amount[0])/determinant]
            proposed.cells=retained(self.cells);proposed.proteins=retained(self.proteins)
            proposed.lost_proteins=self.lost_proteins+flush_out*proposed.proteins[1]/circuit_volume
            proposed.lost_cells=self.lost_cells+flush_out*proposed.cells[1]/circuit_volume
            if network is not None:
                from .distributed import retained
                cells,proteins=retained(self,request,v,network)
                proposed.cells= cells[0];proposed.lost_cells=self.lost_cells+cells[1]
                proposed.proteins=proteins[0];proposed.lost_proteins=self.lost_proteins+proteins[1]
            proposed.vascular=v;proposed.refill_total=self.refill_total+refill
        snapshot = validate_snapshot(proposed.snapshot(), self.online, self.lifecycle)
        self.__dict__.update(proposed.__dict__)
        return snapshot

